// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 depositAmount, address depositor) public {
        depositAmount = bound(depositAmount, 1, 1 ether);
        vm.assume(depositor != address(0));

        Attacker attacker = new Attacker(address(c));

        vm.deal(depositor, depositAmount);
        vm.deal(address(attacker), depositAmount);

        vm.prank(depositor);
        c.addToBalance{value: depositAmount}();

        vm.prank(address(attacker));
        c.addToBalance{value: depositAmount}();

        bool ok;
        try attacker.attackWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.getBalance(address(attacker)) == 0);
    }
}

contract Attacker {
    Reentrance target;
    bool entered;
    constructor(address _t) { target = Reentrance(_t); entered = false; }

    function attackWithdraw() external {
        target.withdrawBalance();
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            try target.withdrawBalance() {
            } catch {
            }
        }
    }
}
